                      } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                        comment.displayTime = entry.gd$extendedProperty[k].value;
                      }
                    }
                  }
                  comments.push(comment);
                }
              }
              return comments;
            };
            var paginator = function(callback) {
              if (hasMore()) {
                var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
                if (cursor) {
                  url += '&published-min=' + new Date(cursor).toISOString();
                }
                window.bloggercomments = function(data) {
                  var parsed = parse(data);
                  cursor = parsed.length < 50 ? null
                      : parseInt(parsed[parsed.length - 1].timestamp) + 1
                  callback(parsed);
                  window.bloggercomments = null;
                }
                url += '&callback=bloggercomments';
                var script = document.createElement('script');
                script.type = 'text/javascript';
                script.src = url;
                document.getElementsByTagName('head')[0].appendChild(script);
              }
            };
            var hasMore = function() {
              return !!cursor;
            };
            var getMeta = function(key, comment) {
              if ('iswriter' == key) {
                var matches = !!comment.author
                    && comment.author.name == config.authorName
                    && comment.author.profileUrl == config.authorUrl;
                return matches ? 'true' : '';
              } else if ('deletelink' == key) {
                return config.baseUri + '/delete-comment.g?blogID='
                     + config.blogId + '&postID=' + comment.id;
              } else if ('deleteclass' == key) {
                return comment.deleteclass;
              }
              return '';
            };
            var replybox = null;
            var replyUrlParts = null;
            var replyParent = undefined;
            var onReply = function(commentId, domId) {
              if (replybox == null) {
                replybox = document.getElementById('comment-editor');
                if (replybox != null) {
                  replybox.height = '250px';
                  replybox.style.display = 'block';
                  replyUrlParts = replybox.src.split('#');
                }
              }
              if (replybox && (commentId !== replyParent)) {
                replybox.src = '';
                document.getElementById(domId).insertBefore(replybox, null);
                replybox.src = replyUrlParts[0]
                    + (commentId ? '&parentID=' + commentId : '')
                    + '#' + replyUrlParts[1];
                replyParent = commentId;
              }
            };
            var hash = (window.location.hash || '#').substring(1);
            var startThread, targetComment;
            if (/^comment-form_/.test(hash)) {
              startThread = hash.substring('comment-form_'.length);
            } else if (/^c[0-9]+$/.test(hash)) {
              targetComment = hash.substring(1);
            }
            var configJso = {
              'maxDepth': config.maxThreadDepth
            };
            var provider = {
              'id': config.postId,
              'data': items,
              'loadNext': paginator,
              'hasMore': hasMore,
              'getMeta': getMeta,
              'onReply': onReply,
              'rendered': true,
              'initComment': targetComment,
              'initReplyThread': startThread,
              'config': configJso,
              'messages': msgs
            };
            var render = function() {
              if (window.goog && window.goog.comments) {
                var holder = document.getElementById('comment-holder');
                window.goog.comments.render(holder, provider);
              }
            };
            if (window.goog && window.goog.comments) {
              render();
            } else {
              window.goog = window.goog || {};
              window.goog.comments = window.goog.comments || {};
              window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
              window.goog.comments.loadQueue.push(render);
            }
          })();
//

body.script:
//
(function () {
  var d = document, html = d.documentElement, path = location.pathname;

  /* Page-type classes for blocks the server can't gate */
  if (/^\/p\/about/.test(path)) { html.className += ' ff-about'; }
  if (/^\/p\/contact/.test(path)) { html.className += ' ff-contact'; }

  /* Current menu item */
  var links = d.querySelectorAll('.ff-nav__list a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i], p = a.pathname.replace(/\/$/, '') || '/';
    var here = path.replace(/\/$/, '') || '/';
    if (p === here) { a.setAttribute('aria-current', 'page'); }
  }

  /* Mobile menu + search toggles */
  function toggler(btnId, panelId, focusSel) {
    var btn = d.getElementById(btnId), panel = d.getElementById(panelId);
    if (!btn || !panel) { return; }
    btn.addEventListener('click', function () {
      var open = panel.classList.toggle('is-open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (open && focusSel) { var f = panel.querySelector(focusSel); if (f) { f.focus(); } }
    });
    d.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && panel.classList.contains('is-open')) {
        panel.classList.remove('is-open');
        btn.setAttribute('aria-expanded', 'false');
        btn.focus();
      }
    });
  }
  toggler('ff-nav-toggle', 'ff-nav', 'a');
  toggler('ff-search-toggle', 'ff-search', 'input');

  /* "N min read" on single posts (about 200 words a minute) */
  var body = d.querySelector('.item .ff-post__body'), rt = d.querySelector('.ff-readtime');
  if (body && rt) {
    var words = (body.innerText || body.textContent || '').split(/\s+/).filter(Boolean).length;
    rt.textContent = Math.max(1, Math.round(words / 200)) + ' min read';
  }

  /* Review scores: a number 1-5 in .ff-score-row span becomes stars */
  var rows = d.querySelectorAll('.ff-post__body .ff-score-row span');
  for (var r = 0; r < rows.length; r++) {
    var el = rows[r], m = (el.textContent || '').replace(',', '.').match(/\d+(\.\d+)?/);
    var n = m ? Math.round(parseFloat(m[0])) : NaN;
    if (isNaN(n)) { continue; }
    n = Math.max(0, Math.min(5, n));
    var stars = d.createElement('i');
    stars.className = 'ff-stars';
    stars.setAttribute('role', 'img');
    stars.setAttribute('aria-label', n + ' out of 5');
    stars.appendChild(d.createTextNode(new Array(n + 1).join('★')));
    var empty = d.createElement('em');
    empty.textContent = new Array(5 - n + 1).join('★');
    stars.appendChild(empty);
    el.textContent = n + '/5';
    el.insertBefore(stars, el.firstChild);
  }

  /* Today's highlights: the 3 newest posts labelled "Highlight" */
  var section = d.getElementById('ff-highlights'), grid = d.getElementById('ff-highlights-grid');
  if (section && grid && window.fetch) {
    fetch('/feeds/posts/summary/-/Highlight?alt=json&max-results=3')
      .then(function (res) { return res.json(); })
      .then(function (data) {
        var entries = (data.feed && data.feed.entry) || [];
        if (!entries.length) { return; }
        entries.forEach(function (e) {
          var url = '#';
          (e.link || []).forEach(function (l) { if (l.rel === 'alternate') { url = l.href; } });
          var cats = (e.category || []).map(function (c) { return c.term; }).filter(function (t) { return t !== 'Highlight'; });
          var img = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s72(-c)?\//, '/w640-h360-p-k-no-nu/').replace(/=s72(-c)?$/, '=w640-h360-p-k-no-nu') : '';
          var card = d.createElement('article'); card.className = 'ff-card';
          var media = d.createElement('a'); media.className = 'ff-card__media'; media.href = url; media.tabIndex = -1; media.setAttribute('aria-hidden', 'true');
          if (img) { var im = d.createElement('img'); im.src = img; im.alt = ''; im.loading = 'lazy'; media.appendChild(im); }
          card.appendChild(media);
          if (cats.length) {
            var eb = d.createElement('p'); eb.className = 'ff-card__eyebrow';
            cats.slice(0, 2).forEach(function (t) { var s = d.createElement('span'); s.textContent = t; eb.appendChild(s); });
            card.appendChild(eb);
          }
          var h = d.createElement('h3'); h.className = 'ff-card__title';
          var ha = d.createElement('a'); ha.href = url; ha.textContent = (e.title && e.title.$t) || '';
          h.appendChild(ha); card.appendChild(h);
          var sum = (e.summary && e.summary.$t) || '';
          if (sum) { var p2 = d.createElement('p'); p2.className = 'ff-card__excerpt'; p2.textContent = sum; card.appendChild(p2); }
          grid.appendChild(card);
        });
        section.hidden = false;
      })
      .catch(function () {});
  }
})();
//
